function validate(input) {
  const [{ Tasks = [] }] = input;
  const keys = new Set(), stamp = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
  for (const [task, employee, start, end] of Tasks) {
    if (task === null || employee === null) return 'Every task needs a task_id and an employee_id.';
    const key = `${task}/${employee}`;
    if (keys.has(key)) return `Task ${task} of employee ${employee} appears twice.`;
    keys.add(key);
    if (!stamp.test(start ?? '') || !stamp.test(end ?? '')) return `Task ${task} needs times like 2023-05-01 08:00:00.`;
    if (!(start < end)) return `Task ${task} must end after it starts.`;
  }
  return null;
}

