function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const stamp = seconds => new Date(Date.UTC(2023, 4, 1) + seconds * 1000).toISOString().slice(0, 19).replace('T', ' ');
  const employees = small ? [1001, 1002, 1003] : Array.from({ length: 40 }, (_, i) => 2001 + i);
  const count = small ? Math.floor(rand() * 9) : 2000;
  // Small cases draw starts and lengths from coarse grids, so equal starts, touching ends and overlaps are common.
  const starts = small ? [8, 8.5, 9, 9.5, 10, 11, 13, 23].map(h => h * 3600) : null;
  const lengths = [900, 1800, 2400, 3600, 5400, 7200, 9000, 3599, 14400];
  const Tasks = [];
  for (let i = 0; i < count; i++) {
    const employee = pick(employees);
    const start = small ? pick(starts) : Math.floor(rand() * 6 * 96) * 900;
    const length = pick(lengths);
    Tasks.push([i + 1, employee, stamp(start), stamp(start + length)]);
  }
  // Small cases sometimes reuse a task_id for different employees, which the key allows.
  if (small && Tasks.length > 1 && rand() < 0.4 && Tasks[0][1] !== Tasks[1][1]) Tasks[1][0] = Tasks[0][0];
  return [{ Tasks }];
}
